// Üretilen dosya: tool/ozgun/uret.py. Sanat · Resim-heykel malzemeleri, boya teknikleri, pigmentler ve sanat eseri restorasyonu (tempera, fresk, yağlıboya, guaj, astar, vernik, konservasyon ilkeleri) (kolay).
const ozArt18Kolay = <(String, String, List<String>, String)>[
  ('Sanat eserlerinin fiziksel veya kimyasal müdahale yapılmadan, ortam koşullarının kontrol altında tutulmasıyla bozulmalarının engellenmesine ne ad verilir?', 'Önleyici koruma', ['Bütüncül tamamlama', 'Yapısal sağlamlaştırma', 'Estetik bütünleme'], 'Önleyici koruma (preventif konservasyon), esere doğrudan müdahale etmeden çevresel etkenleri düzenleyerek bozulmayı önlemeyi amaçlar.'),
  ('Müzelerde ışığın sanat eserleri üzerindeki aydınlatma şiddetini ölçmek için kullanılan birim aşağıdakilerden hangisidir?', 'Lüks', ['Lümen', 'Kandela', 'Kelvin'], 'Aydınlatma şiddeti birim yüzeye düşen ışık akısını ifade eder ve lüks (lux) birimiyle ölçülür.'),
  ('Güneş ışığı ve floresan lambalardan yayılan hangi ışın türü, yüksek enerjisi nedeniyle organik pigmentlerde solmaya ve kâğıtta gevrekleşmeye yol açar?', 'Ultraviyole ışınları', ['Kızılötesi ışınları', 'Radyo dalgaları', 'Mikrodalga ışınları'], 'Kısa dalga boylu ve yüksek enerjili ultraviyole (UV) ışınları kimyasal bağları kopararak fotoliz ve solmaya neden olur.'),
  ('Ahşap paneller, fildişi ve parşömen gibi nem alışverişi yapan malzemeler konservasyon terminolojisinde nasıl adlandırılır?', 'Higroskopik malzemeler', ['Hidrofobik malzemeler', 'Termoplastik malzemeler', 'İnorganik malzemeler'], 'Ortamın bağıl nemine bağlı olarak su buharı alıp veren organik kökenli malzemelere higroskopik malzemeler denir.'),
  ('Müze depolarında bağıl nemin uzun süre %65-%70 seviyesinin üzerinde seyretmesi organik eserlerde en çok hangi tehlikeyi tetikler?', 'Küf ve mantar gelişimi', ['Tuz kristalleşmesi sonucu tozlaşma', 'Parşömen yapraklarının aşırı sertleşmesi', 'Boya yüzeyinde kuruma çatlakları oluşması'], 'Yüksek bağıl nem ve durgun hava, selüloz ve protein bazlı organik malzemeler üzerinde mikroorganizma ve küf sporlarının hızla çoğalmasına yol açar.'),
  ('Müze ortamında sıcaklık ve bağıl nem değerlerini sürekli olarak kaydeden geleneksel mekanik cihaza ne ad verilir?', 'Termohigrograf', ['Spektrofotometre', 'Lüksmetre', 'Refraktometre'], 'Termohigrograf, ortamın sıcaklık (termo) ve bağıl nem (higro) değişimlerini zaman bağlı olarak kâğıt şerit üzerine kaydeden cihazdır.'),
  ('Yağlıboya tabloların en üst yüzeyine boya katmanını dış etkenlerden korumak ve renk doygunluğunu artırmak amacıyla sürülen şeffaf reçine tabakasına ne ad verilir?', 'Vernik', ['Astar', 'Tutkal sürgü', 'Fiksatif'], 'Vernik, boya tabakasını toz, is ve mekanik aşınmadan koruyan, aynı zamanda kırılma indisiyle renkleri derinleştiren şeffaf koruyucu katmandır.'),
  ('Geleneksel yağlıboya resim sanatında yüzyıllar boyunca en yaygın kullanılan iki doğal ağaç reçinesi verniği aşağıdakilerden hangileridir?', 'Dammar ve mastik', ['Epoksi ve poliüretan', 'Akrilik ve polivinil asetat', 'Gomalak ve selüloz nitrat'], 'Sakız ağacından elde edilen mastik ve tropikal ağaçlardan elde edilen dammar, geleneksel tablo verniklerinde en sık kullanılan doğal triterpenoid reçinelerdir.'),
  ('Tablo, ikona veya seramik sırlarının yüzeyinde zamanla oluşan ince çatlak ağlarına sanat tarihi ve konservasyon terminolojisinde ne ad verilir?', 'Kraklür', ['Pentimento', 'Sfumato', 'İmpasto'], 'Fransızca kökenli kraklür terimi, yaşlanma, kuruma veya mekanik gerilimler sonucu boya, vernik ya da sır katmanlarında beliren çatlak dokusunu tanımlar.'),
  ('Koruma etiğinde kullanılan ve uygulanan her türlü malzemenin gelecekte esere hiçbir zarar vermeden çıkarılabilmesini şart koşan temel ilke hangisidir?', 'Geri döndürülebilirlik (tersinirlik) ilkesi', ['Tam yenileme (rekonstrüksiyon) ilkesi', 'Stilistik bütünlük ilkesi', 'Mutlak görünmezlik ilkesi'], 'Geri döndürülebilirlik (reversibility), bugün yapılan rötuş, vernik veya yapıştırma işlemlerinin ileride daha iyi yöntemler geliştiğinde özgün dokuya zarar vermeden geri alınabilmesini öngörür.'),
  ('Bir sanat eserinin korunması için yalnızca zorunlu olduğu kadar işlem yapılmasını ve gereksiz müdahalelerden kaçınılmasını savunan etik ilke hangisidir?', 'En az müdahale (minimum müdahale) ilkesi', ['Kapsamlı yeniden yapım ilkesi', 'Yaratıcı tamamlama ilkesi', 'Ticari değer artırma ilkesi'], 'En az müdahale ilkesi, eserin özgün maddesini ve tarihsel kanıt değerini korumak adına koruma amacına ulaşacak en sınırlı işlemin seçilmesini emreder.'),
  ('Koruma etiğine göre, bir eserin eksik bölümlerine yapılan tamamlamaların (entegrasyonların) izleyici tarafından nasıl algılanması hedeflenir?', 'Normal izleme mesafesinden bütünlüğü sağlamalı, ancak yakından bakıldığında özgün kısımdan ayırt edilebilmelidir', ['Hem uzaktan hem de büyüteçle bakıldığında özgün boyadan kesinlikle ayırt edilememelidir', 'Özgün eseri gölgede bırakacak kadar parlak fosforlu renklerle uzaktan hemen belli olmalıdır', 'Eksik kısımlar her zaman parlak yaldızlı varakla kaplanarak dikkat çekici kılınmalıdır'], 'Cesare Brandi ve Venedik Tüzüğü ilkelerine göre tamamlama sanatsal okumayı kesintiye uğratmamalı fakat yakından incelendiğinde aldatıcı olmamalı, ayırt edilebilir kalmalıdır.'),
  ('Bir sanat eserine herhangi bir konservasyon veya restorasyon müdahalesi yapılmadan önce, işlem sırasında ve işlem sonrasında fotoğraf, çizim ve yazılı raporlarla kayıt tutulması hangi etik zorunluluğun gereğidir?', 'Belgeleme (dokümantasyon) ilkesi', ['Gizlilik ve ticari sır ilkesi', 'Anonimleştirme ilkesi', 'Serbest doğaçlama ilkesi'], 'Yapılan her müdahale, kullanılan malzemeler ve eserin önceki durumu gelecek kuşak araştırmacıları ve konservatörleri için eksiksiz biçimde belgelenmelidir.'),
  ('Bir eserde kayıp bölümün nasıl olduğu hakkında hiçbir fotoğraf, çizim veya kesin fiziksel kanıt bulunmadığında restoratörün nasıl hareket etmesi gerekir?', 'Varsayıma dayalı figür veya motif uydurmamalı, kaybı nötr veya dokusal yöntemle bütünlemelidir', ['Ressamın diğer tablolarından beğendiği bir figürü kopyalayarak boşluğa resmetmelidir', 'Boş kalan alana kendi imzasını ve restorasyon tarihini büyük harflerle yazmalıdır', 'Eksik bölümü kesip atarak tablonun boyutlarını küçültüp yeniden çerçevelemelidir'], 'Venedik Tüzüğü\'nün temel kuralı uyarınca restorasyon varsayımın başladığı yerde durur; kanıt yoksa sanatsal uydurma (hipotetik rekonstrüksiyon) yapılamaz.'),
  ('Deprem bölgesindeki müzelerde heykel, seramik ve cam eserlerin vitrin içinde devrilmesini önlemek için kaide bağlantıları, misina sabitlemeleri ve sismik yalıtıcılar kullanılması hangi koruma kapsamına girer?', 'Önleyici koruma', ['Kimyasal restorasyon', 'Kromatik tamamlama', 'Stilistik yenileme'], 'Eserin kendisine kimyasal müdahale yapmadan fiziksel yıkım risklerini azaltan sismik sabitleme tedbirleri doğrudan önleyici koruma uygulamasıdır.'),
  ('Müze eserlerinin eldivensiz çıplak elle tutulmasının özellikle metal ve kâğıt yüzeylerde sakıncalı olmasının temel nedeni nedir?', 'Ciltteki ter, yağ ve asitlerin yüzeyde korozyon ve kalıcı leke oluşturması', ['Parmak izinin eserin ağırlığını kalıcı olarak iki katına çıkarması', 'İnsan vücut elektriğinin boyadaki pigmentleri mıknatıs gibi sökmesi', 'El sıcaklığının seramik sırlarını anında eriterek akıtması'], 'İnsan cildindeki tuzlu ter, laktik asit ve sebum yağları metallerde parmak izi korozyonuna, kâğıt ve fotoğraflarda ise bozulma ve lekelenmeye yol açar.'),
  ('Konservatör-restoratörün bir esere müdahale etmeden önce eserin malzemesini, yapım tekniğini ve bozulma nedenlerini bilimsel yöntemlerle araştırması sürecine ne denir?', 'Teşhis ve durum tespiti', ['Kromatik bütünleme', 'Ticari ekspertiz fiyatlandırması', 'Replika çoğaltma'], 'Tıpta olduğu gibi korumada da doğru tedavi ancak doğru teşhisle mümkündür; işlem öncesi malzeme ve bozulma durumu bilimsel olarak saptanır.'),
  ('İtalyan restorasyon ekolünde boya kaybı olan alanların (lakünaların) ince, dikey ve yan yana suluboya çizgilerle tamamlanması tekniğine ne ad verilir?', 'Tratteggio', ['Sfumato', 'Chiaroscuro', 'Grattage'], 'Roma Merkez Restorasyon Enstitüsü\'nde geliştirilen tratteggio (rigatino), kayıp alanı dikey paralel ince fırça çizgileriyle tamamlayarak uzaktan bütünlük, yakından ayırt edilebilirlik sağlar.'),
  ('Tratteggio tekniğinin koruma etiğindeki "ayırt edilebilirlik" ilkesini karşılama biçimi aşağıdakilerden hangisidir?', 'Uzaktan bakıldığında resimle kaynaşırken yakından bakıldığında dikey çizgi dokusuyla özgün boyadan netçe ayrılması', ['Tamamlanan bölgenin karanlıkta parlayan fosforlu boyayla işaretlenmesi', 'Rötuş yapılan her lakünanın etrafına kalın siyah bir kontur çizgisi çekilmesi', 'Tamamlamanın özgün yüzeyden bir santimetre daha yüksek kabartma olarak bırakılması'], 'Yaklaşık 1-2 metre mesafeden çizgiler seçilemez ve kompozisyon bütünlenir; yaklaşıldığında ise ince dikey tarama dokusu restorasyonu dürüstçe belli eder.'),
  ('Tarihi kâğıtların (özellikle 19. yüzyıl ortasından itibaren üretilenlerin) zamanla sararıp kahverengileşerek kırılgan hale gelmesinin en temel kimyasal nedeni nedir?', 'Asidik bozulma', ['Aşırı bazikleşme ve kireçlenme', 'Selüloz liflerinin metalleşmesi', 'Kâğıttaki su oranının %90\'a çıkması'], 'Odun hamurundaki lignin ve üretimde kullanılan şap (alüminyum sülfat) asidik ortam yaratarak selüloz zincirlerini koparır ve kâğıdı gevrekleştirir.'),
  ('Kâğıt konservasyonunda "asitsizleştirme" (deacidification) işleminin iki temel hedefi aşağıdakilerden hangisidir?', 'Mevcut serbest asitleri nötralize etmek ve gelecekteki asit oluşumuna karşı kâğıtta alkali rezerv bırakmak', ['Kâğıttaki tüm mürekkep yazılarını silip kâğıdı bembeyaz yeni bir sayfaya dönüştürmek', 'Selüloz liflerini eriterek kâğıdı şeffaf plastik bir filme çevirmek', 'Kâğıdın ağırlığını on kat artırarak rüzgârda uçmasını engellemek'], 'Başarılı bir asitsizleştirme hem pH değerini nötr/hafif bazik düzeye (pH 7,5-9,0) çıkarır hem de kalsiyum veya magnezyum karbonat şeklinde koruyucu bir alkali tampon (rezerv) bırakır.'),
  ('Tarihi gravür, suluboya ve belgelerin çerçevelenmesinde veya depolanmasında kullanılan paspartu ve saklama kutularının hangi temel özelliğe sahip olması gerekir?', '%100 pamuk linterinden veya alfa-selülozdan üretilmiş, ligninsiz, asitsiz ve genellikle kalsiyum karbonat tamponlu (müze kalitesi) olması', ['Maliyeti düşürmek için ham oluklu mukavva ve geri dönüştürülmüş gazete hamurundan yapılması', 'Eseri sıkıca tutması için yüzeyinin PVC bant ve kauçuk zamkla kaplanması', 'Renginin kararmaması için şap ve kolofonyum reçinesiyle sertleştirilmesi'], 'Asidik mukavvalar temas ettikleri esere asit göçü (acid migration) yaparak kenarlardan sararma (mat burn) oluşturur; bu nedenle arşivsel/müze kalitesi paspartu kullanılır.'),
  ('Bir sanat eserinin ünlü bir ustaya aitmiş gibi gösterilmek üzere aldatma amacıyla üretilmesine veya mevcut bir eserin imzasının/tarihinin değiştirilmesine ne ad verilir?', 'Sanat sahteciliği', ['Atölye replikası', 'Eğitim kopyası', 'Önleyici konservasyon'], 'Kopya ve replikalardan farklı olarak sahtecilikte (forgery) alıcıyı, kurumu veya sanat tarihçilerini yanıltarak haksız kazanç veya itibar sağlama kastı vardır.'),
  ('Ressamın resmi yaparken fikrini değiştirip bir figürün veya nesnenin yerini kaydırması ve zamanla üstteki yağlıboyanın şeffaflaşması ya da X-ışını/IRR incelemesiyle bu eski halin görünmesine ne denir?', 'Pentimento', ['Kraklür', 'Tratteggio', 'Sfumato'], 'İtalyanca "pişmanlık / fikir değiştirme" anlamına gelen pentimento, eserin kopya değil özgün yaratım sürecinin ürünü olduğunu destekleyen önemli bir kanıttır.'),
  ('Yırtılmış bir tuval tablonun arkasından kalın bez yamalarla ütülenerek onarılması yerine, kopan keten ipliklerin mikroskop altında tek tek uç uca mikro-yapıştırıcıyla birleştirilmesi yöntemi hangi etik ilkenin en rafine örneğidir?', 'En az müdahale', ['Tam yenileme ve yeniden dokuma', 'Kromatik soyutlama', 'Anoksik dezenfeksiyon'], 'Winfried Heiber tarafından geliştirilen iplikten ipliğe yırtık onarımı, arka yüze kaba yama yapıştırmadan tuvalin özgün gerginliğini ve dokusunu en az müdahaleyle geri kazandırır.'),
  ('Tarihi bir halı veya düz dokuma (kilim) duvarda sergilenirken çivilerle noktasal olarak asmak yerine üst kenar boyunca dikilmiş bir kumaş şeride tutturulan cırt bant (Velcro) sistemiyle asılmasının nedeni nedir?', 'Ağırlığı tüm en boyunca eşit dağıtarak dokuma liflerinin noktasal gerilimle yırtılmasını ve sarkmasını önlemek', ['Halının içindeki güveleri statik elektrik üreterek uzaklaştırmak', 'Yün liflerindeki doğal boyaların ışığa karşı direncini on kat artırmak', 'Dokumanın arka yüzünün hava almasını tamamen engellemek'], 'Noktasal çivi veya mandallar tüm ağırlığı birkaç çözgü ipliğine bindirip yırtılma yaratır; kesintisiz Velcro askı sistemi ise yükü homojen biçimde dağıtır.'),
  ('Müzelerde sergilenen sanat eserlerinin fotoğrafının çekilirken flaş kullanımının yasaklanmasının önleyici koruma açısından mantığı nedir?', 'Binlerce ziyaretçinin yoğun ışık ve UV içeren flaş patlatmasının kümülatif ışık maruziyetini (lüks·saat) artırması', ['Tek bir fotoğraf flaşının mermer heykelleri anında ortadan ikiye çatlatması', 'Flaş ışığının müze güvenlik kameralarının lenslerini eritmesi', 'Fotoğraf makinesi sesinin yağlıboya tabloların verniğini sarartması'], 'Tek bir modern flaş tek başına eseri yakmasa da yılda yüz binlerce ziyaretçinin flaş patlatması toplam ışık dozunu (Bunsen-Roscoe yasası gereği) hızla yükseltir ve ziyaretçi deneyimini bozar.'),
  ('Yağlıboya üretiminde toz pigmentleri birbirine ve yüzeye tutturmak amacıyla geleneksel olarak en yaygın kullanılan bitkisel bağlayıcı hangisidir?', 'Keten yağı', ['Zeytinyağı emülsiyonu', 'Arap zamkı çözeltisi', 'Saf terebentin ruhu'], 'Keten tohumundan elde edilen bezir yağı (keten yağı), havadaki oksijenle tepkimeye girerek sertleşen kuruyucu bir yağ olduğu için yağlıboyanın temel bağlayıcısıdır.'),
  ('Yağlıboyayı inceltmek ve fırçaları temizlemek amacıyla sıklıkla kullanılan, çam reçinesinin damıtılmasıyla elde edilen uçucu çözücü hangisidir?', 'Terebentin', ['Gliserin sıvısı', 'Polimer emülsiyon', 'Saf keten tohumu yağı'], 'Çam ağaçlarının reçinesinden damıtılarak üretilen terebentin, yağlıboyayı akışkanlaştırmak ve çalışma bitiminde fırçaları arındırmak için kullanılan geleneksel incelticidir.'),
  ('Yağlıboya tekniğinin suluboya veya akriliğe kıyasla sanatçıya günlerce sürebilen ıslak zeminde kaynaştırma (harmanlama) olanağı tanımasının temel nedeni nedir?', 'Geç kuruması', ['Suyla çözünmesi', 'Matlaşarak çökmesi', 'Kâğıda hızla işlemesi'], 'Yağlıboya buharlaşarak değil, keten yağının oksidasyonu ve polimerizasyonu ile çok yavaş sertleştiği için yüzey üzerinde uzun süre rötuş ve renk geçişi yapılmasına izin verir.'),
  ('Akrilik boyaların üretiminde pigmentleri bir arada tutan ve kuruduğunda suya dayanıklı esnek bir film tabakası oluşturan bağlayıcı madde nedir?', 'Su bazlı akrilik polimer', ['Kurutulmuş yumurta sarısı', 'Eritilmiş doğal balmumu', 'Keten tohumu bezir yağı'], 'Akrilik boyalar, su bazlı sentetik akrilik polimer emülsiyonunun pigmentlerle karıştırılmasıyla üretilir; su buharlaştığında esnek ve kalıcı bir plastik katmana dönüşür.'),
  ('Islak haldeyken suyla kolayca inceltilebilen akrilik boyanın, tuval üzerinde tamamen kuruduktan sonra suyla yeniden çözünmemesinin sebebi nedir?', 'Polimer zincirlerinin birleşerek suya dirençli film oluşturması', ['İçindeki keten yağının havayla temas edip reçineleşmesi', 'Yüzeydeki kireç sıvanın karbonatlaşarak taşlaşması', 'Arap zamkının kâğıt lifleriyle geri dönüşsüz kaynaşması'], 'Akrilik boyadaki su uçtuğunda asılı duran polimer parçacıkları birbirine kenetlenir ve suyun tekrar çözemeyeceği sürekli, plastik benzeri bir tabaka meydana getirir.'),
  ('Geleneksel şeffaf suluboya tekniğinde resmin en parlak beyaz alanlarını ve ışık vurgularını elde etmek için standart uygulama hangisidir?', 'Beyaz boya kullanmayıp kâğıdın kendi beyazlığını boş bırakmak', ['Yüzeye kalın katmanlar halinde çinko beyazı sürmek', 'Kuruyan boyanın üzerini terebentinli bezle kazımak', 'Zemine önceden yumurta akı ve tebeşir tozu karıştırmak'], 'Klasik suluboyada boya katmanları saydam olduğu için ışık alttaki beyaz kâğıttan yansır; bu yüzden açık tonlar suyla inceltilerek, tam beyazlar ise kâğıt boyanmadan bırakılarak sağlanır.'),
  ('Suluboya ve guaj boyaların üretiminde pigmentleri bağlamak için kullanılan, akasya ağacının özsuyundan elde edilen doğal madde hangisidir?', 'Arap zamkı', ['Çam terebentini', 'Polimer reçinesi', 'Haşhaş tohumu yağı'], 'Akasya türlerinden toplanan ve suda kolayca çözünen Arap zamkı, hem şeffaf suluboyanın hem de örtücü guaj boyanın ana geleneksel bağlayıcısıdır.'),
  ('Guaj boyayı geleneksel suluboyadan ayıran ve alttaki koyu renklerin bile tek katta kapatılabilmesini sağlayan en belirgin görsel özellik nedir?', 'Yüksek örtücülük', ['Tam saydamlık ve parlaklık', 'Suya karşı mutlak direnç', 'Isıtılarak yüzeye sürülme'], 'Guaj boya, daha iri öğütülmüş yüksek oranlı pigment ve tebeşir (kalsiyum karbonat) gibi matlaştırıcı dolgular içerdiğinden ışığı geçirmez ve yüksek örtücülük sunar.'),
  ('Suluboya çalışmalarında fazla suyu emmesi, kabarmayı azaltması ve dokulu bir yüzey sunması nedeniyle en çok tercih edilen yüksek gramajlı kâğıt hammaddesi nedir?', 'Yüzde yüz pamuk lifi', ['Parlak kuşe selülozu', 'Yağlı parşömen tabakası', 'Saman kâğıdı hamuru'], 'Pamuk liflerinden (cotton rag) üretilen suluboya kâğıtları, odun selülozuna göre çok daha uzun liflidir; bol suyu bünyesinde dengeli tutar, ıslak üstüne ıslak tekniğine dayanır ve sararmaz.'),
  ('Suluboyada önceden temiz suyla nemlendirilmiş kâğıt yüzeyine ıslak fırçayla boya bırakılarak yumuşak, sınırları belirsiz dağılmalar elde edilen tekniğe ne ad verilir?', 'Islak üstüne ıslak (wet-on-wet)', ['Kuru fırça taraması (drybrush)', 'Kazıma tekniği (sgraffito)', 'Kalın hamur sürümü (impasto)'], 'Kâğıt yüzeyi nemliyken uygulanan ıslak boya, suyun kılcal hareketiyle lifler boyunca kendiliğinden yayılarak keskin kenarlar olmadan yumuşak geçişler oluşturur.'),
  ('Yağlıboyada tek bir oturumda, alt katmanların kurumasını beklemeden ıslak boya üzerine ıslak boya sürerek resmi doğrudan bitirme yöntemine ne ad verilir?', 'Alla prima (doğrudan boyama)', ['Grisaille (monokrom alt resim)', 'Chiaroscuro (ışık-gölge zıtlığı)', 'Sfumato (dumanlı tül geçişi)'], 'İtalyanca "ilk seferde" anlamına gelen alla prima, katmanların haftalarca kurumasını beklemeden tüm eserin boya henüz ıslakken tek aşamada tamamlanmasıdır.'),
  ('Yağlıboyada boyanın macun kıvamında, fırça veya resim bıçağı (spatula) izlerini belirgin biçimde koruyacak kadar kalın sürülmesi tekniğine ne denir?', 'İmpasto', ['Glazür', 'Lavaj', 'Frotaj'], 'İmpasto tekniğinde boya inceltilmeden veya yoğunlaştırıcı medyumlarla kalın katmanlar halinde yüzeye bırakılır; kuruduğunda üç boyutlu rölyef etkisi ve ışık oyunları yaratır.'),
  ('Kapalı stüdyo ortamında terebentin kokusu ve buharının solunum yollarına verdiği zarardan kaçınmak isteyen yağlıboya sanatçıları inceltici olarak neyi tercih eder?', 'Kokusuz mineral ispirto', ['Yüksek asitli üzüm sirkesi', 'Saf aseton ve selülozik tiner', 'Sıcak su ve Arap zamkı'], 'Aromatik hidrokarbonları arındırılmış kokusuz mineral ispirtolar (odorless mineral spirits), doğal terebentine göre çok daha az zararlı buhar çıkarır ve yağlıboyayı güvenle inceltir.'),
  ('Akrilik boyalarla çalışırken fırçaların boya sertleşmeden temizlenmesi için kullanılan temel sıvı nedir?', 'Su', ['Saf çam terebentini', 'Keten tohumu yağı', 'Eritilmiş sıcak balmumu'], 'Akrilik boyalar ıslakken su bazlı olduğu için fırçalar kurumadan önce su ve sabunla kolayca temizlenir; ancak fırçada kurursa suyla çıkmaz.'),
  ('Suluboyada geniş bir yüzeyi tek ve homojen bir renk tonuyla fırça izi bırakmadan kaplama işlemine ne ad verilir?', 'Düz yıkama (flat wash)', ['Noktalama (stippling)', 'Kazıma (sgraffito)', 'Kalın sıva (impasto)'], 'Eğimli tutulan kâğıt üzerinde her yatay fırça darbesinin alt kenarında biriken boya damlasını (bead) bir alt satıra taşıyarak yapılan tekdüze boyamaya düz yıkama (lavaj) denir.'),
  ('Guaj boyanın afiş tasarımı, illüstrasyon ve animasyon arka planlarında (örneğin klasik stüdyo çalışmalarında) uzun yıllar tercih edilmesinin başlıca nedeni nedir?', 'Düz, lekesiz, yansıma yapmayan mat ve tam örtücü renk alanları oluşturması', ['Güneş altında bile aylarca kurumadan ıslak kalabilmesi', 'Sürüldüğü yüzeyi cam gibi parlak ve şeffaf göstermesi', 'Terebentin ile inceltildiğinde ahşap şasiyi sertleştirmesi'], 'Guaj boya kuruduğunda ışığı yansıtmayan kadifemsi mat ve homojen renk yüzeyleri sunduğu için fotoğrafik çoğaltma ve kamera çekimlerinde parlama yapmaz.'),
  ('Yağlıboyada renkleri karıştırmak için kullanılan geleneksel ahşap paletin, boyanın içindeki yağı emmemesi için ilk kullanımdan önce ne ile doyurulması gerekir?', 'Keten yağı', ['Sıcak su ve tuz', 'Arap zamkı şurubu', 'Kireçli duvar sıvası'], 'Ham ahşap palet keten yağıyla birkaç kat silinip kurutularak doyurulur; aksi halde ahşap boyadaki bağlayıcı yağı emer ve boyayı tuvale mat, yağsız ve dayanıksız taşır.'),
  ('Suluboya tekniğinde bol miktarda su ve boya tutma kapasitesi ile sivri uç toplama yeteneği sayesinde en değerli kabul edilen doğal fırça kılı hangisidir?', 'Samur kılı', ['Sert yaban domuzu kılı', 'Kalın tel fırça lifi', 'Doğal jüt keneviri'], 'Kolinsky samuru kılları karın kısmında bol su depolarken uca doğru iğne gibi incelir; böylece tek fırçayla hem geniş yıkamalar hem kılcal detaylar yapılabilir.'),
  ('Akrilik boyaların duvar resminde (mural) geleneksel yağlıboyaya göre dış mekânlarda çok daha sık tercih edilmesinin temel nedeni nedir?', 'Hızlı kuruması, esnek kalması ve alkali beton/sıva yüzeylerde sabunlaşmadan dayanması', ['Yağmur yağdığında yeniden çözünüp kendi kendini temizlemesi', 'Yalnızca ıslak kireç sıvası içine gömülerek taşlaşması', 'Güneş ısısıyla eriyip duvar çatlaklarını balmumu gibi doldurması'], 'Keten yağı alkali (bazik) çimento ve kireçli duvarlarda "sabunlaşma" (saponification) tepkimesine girip bozulurken, akrilik polimerler alkali yüzeylere dirençlidir, hızla kurur ve hava koşullarına esnek uyum sağlar.'),
  ('Yağlıboyada tuval üzerinde ıslak veya yarı kuru boyayı kazıyarak alttaki kontrast rengi ya da astarı çizgisel olarak ortaya çıkarma tekniğine ne ad verilir?', 'Sgraffito', ['Glazürleme', 'Sfumato', 'Noktacılık'], 'İtalyanca "kazımak" fiilinden türeyen sgraffito, fırça sapı, kemik kalem veya spatulayla üstteki ıslak boya tabakasını çizerek alt katmanın rengini gösterme tekniğidir.'),
  ('Suluboya boyalarının piyasada sanatçılara sunulduğu başlıca iki geleneksel form hangisidir?', 'Kuru tablet (pan) ve nemli tüp', ['Toz tebeşir çubuk ve sprey kutu', 'Sıcak kalıp mum ve cam kavanoz vernik', 'Kireç torbası ve bezir yağı şişesi'], 'Suluboyalar ya küçük dikdörtgen kaplarda kurutulmuş katı tablet (godet/pan) halinde ya da gliserin oranı biraz daha yüksek macunsu tüpler halinde üretilir.'),
  ('Guaj boyanın kuruduktan sonra kâğıt üzerinde çatlayıp dökülmemesi için sanatçının kaçınması gereken uygulama hangisidir?', 'Boyayı yağlıboya veya akrilikteki gibi çok kalın (impasto) katmanlar halinde sürmek', ['Boyayı temiz suyla incelterek ince ve homojen katmanlar halinde uygulamak', 'Yüksek gramajlı pamuklu suluboya kâğıdı veya illüstrasyon kartonu kullanmak', 'Fırçaları çalışma bitiminde ılık suyla yıkayarak zamk kalıntısından arındırmak'], 'Guajdaki Arap zamkı ve yoğun dolgu maddesi kalın kütleler halinde kuruduğunda esnek değildir; kâğıt esnediğinde kalın guaj tabakası çatlar ve pul pul dökülür.'),
  ('Akrilik boyaların kıvamlarına göre sınıflandırılmasında, yağlıboya gibi tereyağı kıvamında olan ve fırça darbesini koruyan standart tüp/kavanoz türüne ne ad verilir?', 'Ağır gövdeli (heavy body) akrilik', ['Mürekkep (ink) akrilik', 'Suluboya tableti', 'Toz pastel bağlayıcısı'], 'Heavy body (ağır gövdeli) akrilikler yüksek viskozitelidir; fırça veya bıçak darbelerini tutar, akışkan (fluid) ve mürekkep (high flow) akrilikler ise düz boyama ve ince çizgiler içindir.'),
  ('Suluboya çalışmalarının sergilenmesi ve korunması aşamasında yağlıboya tablolardan farklı olarak genellikle UV korumalı camlı çerçeve içine alınmasının nedeni nedir?', 'Kâğıt zeminin ve ince bağlayıcılı su bazlı boya tabakasının neme, toza, sürtünmeye ve ışıkla solmaya karşı çok hassas olması', ['Suluboyanın cam arkasında havasız kalmazsa buharlaşıp kâğıttan uçması', 'Camın kâğıttaki keten yağını emerek resmi kurutması', 'Suluboya kâğıdının kendi ağırlığıyla çerçeveden eriyip akması'], 'Yağlıboya vernikle korunabilen dayanıklı bir film oluştururken, suluboya verniklenmez (vernik şeffaflığını ve mat kâğıt dokusunu bozar); bu yüzden cam altında nem ve UV ışığından korunur.'),
  ('Akrilik boyanın parlaklık derecesini değiştirmek isteyen bir sanatçı, parlak kuruyan akrilik boyayı matlaştırmak için boyaya hangi yardımcı malzemeyi karıştırır?', 'Mat medyum', ['Saf bezir yağı', 'Kristal dammar verniği', 'Sıcak balmumu kalıbı'], 'İçerisinde mikroskobik matlaştırıcı silika tanecikleri barındıran akrilik mat medyum, boyanın plastik parlaklığını kırarak saten veya tamamen mat bir yüzey elde edilmesini sağlar.'),
  ('Akrilik boyanın kolaj ve karışık teknik (mixed media) çalışmalarında hem boya hem de yapıştırıcı olarak kullanılabilmesinin nedeni nedir?', 'Akrilik polimer emülsiyonun kuruduğunda yüksek yapışma gücüne sahip, şeffaf ve asitsiz esnek bir bağlayıcı olması', ['İçindeki terebentinin kâğıt ve kumaş parçalarını eriterek tuvale kaynatması', 'Yumurta sarısı içerdiği için kuruduktan sonra vernik gerektirmemesi', 'Isıtıldığında mum gibi eriyip ağır metal parçaları bile tutabilmesi'], 'Akrilik jel ve mat medyumlar saf akrilik polimer reçinesidir; kâğıt, kumaş ve hafif nesneleri sararmadan, asit hasarı vermeden tuvale güçlü biçimde yapıştırır.'),
  ('Yağlıboyada tuval üzerindeki renkleri yumuşakça birbirine kaynaştırmak ve fırça izlerini silmek için kuru olarak hafifçe dokundurulan yelpaze veya yumuşak kıllı fırça işlemine ne denir?', 'Harmanlama / kaynaştırma (blending)', ['Kazıma (sgraffito)', 'Sıçratma (spattering)', 'Maskeleme (masking)'], 'Yağlıboya uzun süre ıslak kaldığından, iki komşu renk sınırı temiz ve yumuşak bir fırçayla (örneğin yelpaze veya porsuk kılı fırça) hafifçe süpürülerek kesintisiz ton geçişi (sfumato etkisi) elde edilir.'),
  ('Geleneksel yumurta temperası (egg tempera) tekniğinde toz pigmentleri yüzeye bağlamak için kullanılan doğal emülsiyon maddesi hangisidir?', 'Yumurta sarısı', ['Sıcak eritilmiş balmumu', 'Saf çam terebentini', 'Sönmüş kireç kaymağı'], 'Geleneksel temperada yumurtanın akı ve zarından ayrılan saf yumurta sarısı suyla inceltilerek toz pigmentlerle karıştırılır; yumurta sarısı su ve yumurta yağından oluşan doğal bir emülsiyondur.'),
  ('Yumurta temperası ile yapılan resimlerin yağlıboyaya göre fırça kullanımında çok daha disiplinli, ince çapraz taramalar (hatching) gerektirmesinin temel nedeni nedir?', 'Saniyeler içinde çok hızlı kuruduğu için ıslak zeminde yumuşak renk kaynaştırmasına izin vermemesi', ['Haftalar boyunca hiç kurumadan tuval yüzeyinden aşağı akması', 'Yalnızca kalın spatulalarla beş santimetre kalınlığında sürülebilmesi', 'Suyla temas ettiğinde anında köpürerek boyayı yok etmesi'], 'Tempera boyası sürüldüğü anda suyunu kaybedip hızla matlaşarak kurur; bu nedenle ton geçişleri boyayı yayarak değil, ince yarı-saydam fırça çizgilerini üst üste tarayarak oluşturulur.'),
  ('Antik Çağ\'da özellikle Feyyum mumya portreleriyle ünlenen "enkostik" (encaustic) resim tekniğinin temel bağlayıcısı nedir?', 'Isıtılarak eritilmiş sıcak balmumu', ['Keten tohumu bezir yağı', 'Akasya ağacı Arap zamkı', 'Su bazlı akrilik polimer'], 'Yunanca "yakarak işlemek" anlamındaki enkostik tekniğinde arı balmumu (sertlik vermesi için az miktar dammar reçinesiyle) ısıtılıp eritilir ve pigmentlerle sıcak halde yüzeye uygulanır.'),
  ('Duvar resmi sanatında taze sürülmüş, henüz ıslak ve prizini almamış kireç sıvası üzerine suyla ezilmiş pigmentlerle yapılan gerçek fresk tekniğine ne ad verilir?', 'Yaş fresk (buon fresco)', ['Kuru fresk (fresco secco)', 'Sıcak mum enkostik', 'Yağlı glazür tekniği'], 'İtalyanca "gerçek/iyi fresk" anlamına gelen buon fresco (yaş fresk), taze ve nemli kireç harcı (intonaco) üzerine bağlayıcısız, yalnız suyla karıştırılmış alkaliye dayanıklı pigmentlerin sürülmesidir.'),
  ('Yaş fresk (buon fresco) tekniğini kuru freskten (fresco secco) çok daha kalıcı ve dış etkenlere dayanıklı kılan kimyasal süreç nedir?', 'Islak sıvadaki kirecin havadaki karbondioksitle birleşip kalsiyum karbonata (kireçtaşına) dönüşürken pigmentleri sıvanın içine hapsetmesi', ['Boyanın içindeki keten yağının duvarın tuğlalarına sızarak plastikleşmesi', 'Yüzeye sürülen sıcak balmumunun duvarın gözeneklerini dışarıdan mühürlemesi', 'Pigmentlerin yumurta akıyla karıştırılarak sıvanın üstünde ince bir vernik oluşturması'], 'Islak sıvadaki kalsiyum hidroksit yüzeye yürür ve havadaki karbondioksiti emerek çözünmez kalsiyum karbonat kristalleri oluşturur (karbonatlaşma); boya duvarın üstünde bir katman değil, bizzat duvarın taşlaşmış yüzeyi olur.'),
  ('Tamamen kurumuş kireç sıvası üzerine yumurta, kazein (süt proteini) veya zamk gibi ek bir bağlayıcıyla karıştırılmış boyaların sürülmesiyle yapılan duvar resmi tekniği hangisidir?', 'Kuru fresk (fresco secco)', ['Yaş fresk (buon fresco)', 'Alla prima yağlıboya', 'Şeffaf suluboya lavajı'], 'İtalyanca "kuru" anlamındaki secco tekniğinde sıva artık karbonatlaşmasını tamamladığı için pigmenti içine çekemez; bu nedenle boyanın duvara tutunması için organik bir bağlayıcı eklenmesi zorunludur.'),
  ('Tuval bezinin gergin ve düz durmasını sağlamak amacıyla dört kenarından üzerine gerilip zımbalandığı ahşap çerçeve iskeletine ne ad verilir?', 'Şasi (tuval kasnağı / stretcher)', ['Şövale (resim sehpası)', 'Palet (karıştırma tablası)', 'Ragle (baskı çekeceği)'], 'Tuval bezinin arkasına görünmeyecek şekilde yerleştirilen, köşeleri geçmeli ahşap çıtalardan oluşan taşıyıcı kasnağa şasi denir; dış dekoratif çerçeveden farklıdır.'),
  ('Ham keten veya pamuklu tuval bezini boyanın asitlerinden korumak, emiciliği dengelemek ve boyanın tutunacağı beyaz/pürüzsüz bir zemin oluşturmak için sürülen astara ne ad verilir?', 'Gesso', ['Terebentin ruhu', 'Dammar son kat verniği', 'Maskeleme gomajı'], 'Gesso, geleneksel olarak alçı/tebeşir ve hayvansal tutkaldan, modern sanatta ise kalsiyum karbonat, titanyum beyazı ve akrilik polimerden oluşan temel zemin hazırlık astarıdır.'),
  ('Tuval şasisinin köşe birleşim yerlerindeki yuvalara çekiçle hafifçe çakılarak zamanla gevşeyen tuval bezini yeniden germeye yarayan küçük üçgen tahta parçalara ne ad verilir?', 'Kama', ['Şövale mandalı', 'Spatula bıçağı', 'Kavela çivisi'], 'Kaliteli tuval şasilerinin köşeleri sabit çivilenmez ve tutkallanmaz, geçmeli (zıvanalı) yapılır; nem değişimiyle sarkan bez, köşelerdeki yarıklara ahşap kamalar çakılıp şasi milimetrik genişletilerek yeniden gerilir.'),
  ('Büyük boyutlu tuval şasilerinde, bez gerildiğinde karşılıklı uzun kenar çıtalarının çekme kuvvetiyle içeri doğru bel vermesini önlemek için şasinin ortasına eklenen destek parçasına ne denir?', 'Orta kayıt / kuşak çıtası', ['Resim paleti', 'Baskı merdanesi', 'Vernik teknesi'], 'Genişliği 70-80 santimetreyi aşan şasilerde ıslanan ve kuruyan bezin çekme kuvveti yan çıtaları yay gibi büker; arkadaki tekli veya artı (+) biçimli orta kayıt çıtaları iskeleti dik tutar.'),
  ('Yaş fresk (buon fresco) tekniğinde pigmentlerin su dışında hiçbir organik bağlayıcı (yağ, zamk, yumurta) gerektirmemesinin nedeni nedir?', 'Taze sıvanın içindeki kireç suyunun kururken bizzat kendisinin mineral bağlayıcı görevi görmesi', ['Duvar tuğlalarının mıknatıs gibi demirli boyaları çekmesi', 'Pigmentlerin sıcak ütüyle duvara eritilerek yapıştırılması', 'Boyanın içine gizlice şeffaf akrilik tutkal katılması'], 'Yaş sıvada çözünen kalsiyum hidroksit boya taneciklerini sarar ve havayla temas edip kalsiyum karbonat (kireçtaşı) ağını örerken pigmentleri kimyasal/kristal kafes içine kilitler.'),
  ('Akrilik gesso ile astarlanmış hazır bir tuvalin yüzeyini çok pürüzlü bulan bir portre ressamı, daha kaygan ve detaya uygun bir zemin elde etmek için boyamadan önce ne yapmalıdır?', 'Kurumuş gesso katmanını ince zımpara kâğıdıyla hafifçe zımparalayıp bir kat daha ince gesso sürerek işlemi tekrarlamalıdır', ['Tuvalin üzerine bol miktarda çam terebentini döküp fırçayla kazımalıdır', 'Gessolu yüzeyi sıcak ütüyle eriterek kumaş dokusunu yakmalıdır', 'Tuvalin arkasına kalın bir kat keten yağı sürüp yumuşatmalıdır'], 'Akrilik gesso katları kuruduktan sonra ince (örneğin 220-400 kum) zımparayla düzleştirilip tozu alınarak 2-3 ince kat halinde uygulandığında fildişi gibi pürüzsüz bir portre yüzeyi verir.'),
  ('Pastel veya kömür yanında akışkan akrilik ve yağlıboyada da özel dokulu zemin oluşturmak için gessoya mermer tozu veya pomza taşı katılmış pütürlü astara ne ad verilir?', 'Dişli / kumlu astar', ['Sıcak baskı kaygan vernik', 'Şeffaf cam glazürü', 'Kokusuz mineral tiner'], 'İnce öğütülmüş pomza (sünger taşı) veya mermer tozu içeren astarlar belirgin bir "diş" (tooth) oluşturur; hem kuru çizim malzemelerini hem de çok katmanlı boyayı güçlü tutar.'),
  ('Tuval bezinin dokuma sıklığı ve kalınlığı değerlendirildiğinde, çok büyük boyutlu (örneğin 2x3 metre) bir yağlıboya tablo için ince patiska yerine hangi bez yapısı seçilmelidir?', 'Ağır gramajlı, sıkı dokunmuş kalın keten veya ağır pamuklu branda', ['Çok seyrek dokunmuş ince tülbent bezi', 'Düşük gramajlı gazete kâğıdı', 'Esnek likralı sentetik jarse kumaş'], 'Geniş açıklıklarda boya katmanlarının ağırlığını sarkmadan ve yırtılmadan taşıyabilmek için yüksek gramajlı (örneğin 400-500 g/m² üzeri), çift iplikli sıkı dokunmuş keten veya branda gerekir.'),
  ('Yumurta temperası, geleneksel gesso veya yağlıboya üretmek isteyen bir sanatçının kuru toz pigmentleri bağlayıcı sıvıyla cam tabla üzerinde homojen şekilde ezmek için kullandığı düz tabanlı cam/taş tokmağa ne denir?', 'Boya ezici', ['Resim şövalesi', 'Germe kaması', 'Maskeleme bandı'], 'Buzlu cam bir levha üzerinde pigment ve bağlayıcı (keten yağı, yumurta sarısı veya Arap zamkı), düz tabanlı cam ezici (muller) ile sekiz (8) çizerek döndürüle döndürüle topaksız hale getirilir.'),
  ('Hazır satılan astarlı tuvallerin etiketlerinde sıkça görülen "evrensel astarlı" (universally primed) ifadesi o tuvalin hangi boya türleriyle kullanılabileceğini belirtir?', 'Hem yağlıboya hem de akrilik boya (ve uygun teknikle alkid/guaj) ile doğrudan çalışmaya uygun akrilik gesso kaplı olduğunu', ['Üzerine yalnızca sıcak balmumu ve yaş kireç sıvası sürülebileceğini', 'Hiçbir astar içermeyip tamamen ham çuval bezinden oluştuğunu', 'Yalnızca şeffaf suluboya yıkamaları için pamuk kâğıttan üretildiğini'], '"Universal primer" yani standart akrilik dispersiyon gessosu, hem su bazlı akrilik polimerleri hem de üstüne "yağsız üstüne yağlı" kuralına uygun olarak sürülen yağlıboyayı güvenle kabul eder.'),
  ('Yumurta temperası eserlerde Orta Çağ ikonaları ve Erken Rönesans panellerinde arka planlara altın yaprak (varak) yapıştırılmadan önce gesso üzerine sürülen ince kızıl/sarı kil tabakasına ne ad verilir?', 'Bolus', ['Terebentin ruhu', 'Sıcak balmumu', 'Akrilik geciktirici'], 'İnce öğütülmüş demir oksitli yumuşak kil (bolus) tavşan derisi tutkalı veya yumurta akıyla gesso üzerine sürülür; yastık görevi görerek üstüne yapıştırılan altın varağın akik taşıyla ayna gibi parlatılmasını (burnishing) sağlar.'),
  ('Yağlıboya, akrilik veya enkostikte boyayı fırça kullanmadan ezmek, karıştırmak ve tuvale keskin düzlemler halinde sıvamak için kullanılan esnek çelik uçlu el aracına ne ad verilir?', 'Resim bıçağı / palet bıçağı', ['Kılavuz çekül ipi', 'Spolvero kesesi', 'Zımpara takozu'], 'Palet bıçağı düz ağızlı olup palet üzerinde boya karıştırmaya yararken, boynu kıvrık ve ucu çok esnek çelikten yapılan resim bıçağı (painting knife / spatula) doğrudan tuvale kalın veya ince boya sürmek için tasarlanmıştır.'),
  ('Yaş fresk veya kuru fresk gibi doğrudan mimari duvar yüzeyine bağlı olarak üretilen büyük ölçekli resim çalışmalarının genel sanat terimi nedir?', 'Duvar resmi', ['Minyatür tezhip', 'Şövale resmi', 'Kolaj asamblaj'], 'Latince "duvar" (murus) sözcüğünden türeyen mural (duvar resmi), taşınabilir şövale tuvallerinden farklı olarak doğrudan bir yapının duvar veya tavan yüzeyine uygulanan resimleri kapsar.'),
  ('Suluboya, guaj, akrilik, yağlıboya, tempera ve enkostik gibi tüm boya türlerinde rengi veren katı maddenin (pigmentin) bağlayıcı sıvı içindeki temel fiziksel durumu nedir?', 'Bağlayıcı içinde kimyasal olarak erimeyip (çözünmeyip) ince öğütülmüş katı tanecikler halinde asılı kalması', ['Bağlayıcı sıvı içinde şeker veya tuz gibi tamamen eriyerek moleküler çözelti oluşturması', 'Havadaki oksijenle birleşip tamamen gaz haline geçmesi', 'Yalnızca elektrik akımı verildiğinde görünür hale gelmesi'], 'Sıvıda tamamen çözünen renklendiricilere "boya maddesi / boyarmadde" (dye) denir (ör. kumaş boyası, mürekkep); resim boyalarındaki "pigmentler" ise bağlayıcıda çözünmeyen katı renk tanecikleridir.'),
  ('Rönesans resim sanatında Meryem Ana\'nın pelerinini boyamak için sıkça kullanılan ve "denizin ötesinden gelen" anlamındaki doğal ultramarin pigmenti hangi yarı değerli taştan elde edilir?', 'Lapis lazuli', ['Bakır karbonat esaslı malakit taşı', 'Demir sülfür içeren pirit kristali', 'Cıva sülfür yapılı zencefre cevheri'], 'Doğal ultramarin pigmenti, Afganistan\'daki madenlerden çıkarılıp deniz yoluyla Avrupa\'ya getirilen lapis lazuli (lacivert taşı) öğütülerek üretilmiştir.'),
  ('Tarih öncesi mağara resimlerinde en yaygın kullanılan sarı, kırmızı ve kahverengi tonlardaki doğal toprak boyalarına genel olarak ne ad verilir?', 'Aşı boyası', ['Çinko beyazı', 'Prusya mavisi', 'Kadmium sarısı'], 'Demir oksit ve kil içeren doğal toprak pigmentleri Türkçede aşı boyası, sanat literatüründe ise okr (ochre) olarak adlandırılır.'),
  ('Söğüt veya asma dallarının havasız ortamda yakılmasıyla elde edilen ve eskiz çalışmalarında kolayca silinebildiği için tercih edilen çizim malzemesi hangisidir?', 'Füzen', ['Sangin', 'Guaj boya', 'Yağlı pastel'], 'Füzen, ince ağaç dallarının oksijensiz ortamda kömürleştirilmesiyle üretilen yumuşak ve mat siyah tonlu geleneksel çizim kömürüdür.'),
  ('Kömür, kuru pastel veya kurşun kalemle yapılan çizimlerin dağılmasını önlemek amacıyla kağıt yüzeyine püskürtülen koruyucu sıvıya ne ad verilir?', 'Fiksatif', ['Terebentin', 'Bezir yağı', 'Arap zamkı'], 'Fiksatif, toz yapılı çizim malzemelerini kağıt liflerine sabitleyerek bulaşmayı ve silinmeyi engelleyen reçine bazlı sabitleyicidir.'),
  ('Mermer, ahşap veya taş gibi sert bir bloktan parça kopararak ve eksilterek form oluşturma esasına dayanan heykel tekniği hangisidir?', 'Yontma', ['Modelaj', 'Bronz döküm', 'Asamblaj'], 'Yontma (eksiltme) tekniği, tek parça sert kütleden keski ve çekiç gibi aletlerle malzeme çıkarılarak heykel yapılmasıdır.'),
  ('Kil, balmumu veya plastilin gibi yumuşak malzemelerin elle ya da şekillendirme çubuklarıyla eklenip yoğrulmasıyla uygulanan heykel yapım tekniği nedir?', 'Modelaj', ['Taş yontma', 'Ahşap oyma', 'Metal dövme'], 'Modelaj (biçimlendirme), esnek ve yumuşak malzemeleri üst üste ekleyip şekillendirerek üç boyutlu form üretme yöntemidir.'),
  ('Bronz ve bakır heykellerin yüzeyinde zamanla doğal korozyonla oluşan ya da kimyasal asitlerle bilinçli olarak yaratılan renkli koruyucu tabakaya ne denir?', 'Patina', ['Fiksatif', 'Astar boya', 'Emülsiyon'], 'Patina, bakır alaşımlarının oksitlenmesi veya sülfatlanmasıyla yüzeyde beliren yeşil, kahverengi ya da mavi tonlu ince tabakadır.'),
  ('Kızıl-kahverengi ve kiremit tonlarıyla Rönesans ustalarının figür ve portre etütlerinde sıkça kullandığı tebeşir benzeri çizim kalemi hangisidir?', 'Sangin', ['Füzen', 'Grafit', 'Gümüş uç'], 'Sangin, hematit (demir oksit) içeren kırmızımsı kahverengi tonuyla özellikle ten dokusu çizimlerinde tercih edilen geleneksel malzemedir.'),
  ('İs karası (karbon) ile gomalak reçinesinin suyla karıştırılmasıyla hazırlanan, kuruduğunda suya dayanıklı parlak siyah bir katman bırakan mürekkep hangisidir?', 'Çini mürekkebi', ['Demir mazı mürekkebi', 'Sepya mürekkebi', 'Ceviz kabuğu mürekkebi'], 'Çini mürekkebi, ince karbon partikülleri ve şellak (gomalak) bağlayıcısı sayesinde kuruduktan sonra suda çözünmeyen yoğun siyah mürekkeptir.'),
  ('Parlak kırmızı-turuncu rengini cıva sülfür bileşiğinden alan ve Orta Çağ tezhiplerinden yağlı boya tablolara kadar geniş kullanım bulan tarihsel pigment hangisidir?', 'Vermilyon', ['Prusya mavisi', 'Koyu lacivert', 'Krom yeşili'], 'Vermilyon, doğal zencefre (cinnabar) mineralinden ya da cıva ile kükürdün yapay birleşiminden elde edilen parlak kırmızı pigmenttir.'),
  ('Sanat tarihinde tesadüfen keşfedilen ilk modern sentetik pigment olarak kabul edilen koyu ve güçlü mavi boya maddesi hangisidir?', 'Prusya mavisi', ['Mısır mavisi', 'Kobalt mavisi', 'Doğal ultramarin'], 'Prusya mavisi, 18. yüzyıl başında Berlin\'de boya yapımcısı Diesbach tarafından demir ferro-siyanür bileşiği olarak tesadüfen üretilmiştir.'),
  ('Antik Çağ\'dan 19. yüzyıla kadar yağlı boya paletlerinin en örtücü ve hızlı kuruyan temel beyazı olan, ancak zehirli yapısı nedeniyle kullanımı kısıtlanan pigment hangisidir?', 'Kurşun beyazı', ['Titanyum beyazı', 'Çinko beyazı', 'Kalsiyum karbonat'], 'Kurşun beyazı (üstübü), bazik kurşun karbonat yapısıyla yüksek örtücülük sağlasa da kurşun zehirlenmesine yol açan toksik bir pigmenttir.'),
  ('Balmumundan yapılan heykel modelinin ateşe dayanıklı kalıp içine alınıp eritilerek boşaltılması ve yerine erimiş metal dökülmesi yöntemine ne ad verilir?', 'Kayıp mum tekniği', ['Kum kalıp dökümü', 'Doğrudan taş yontma', 'Soğuk seramik dökümü'], 'Fransızca cire perdue olarak da bilinen kayıp mum tekniği, mum modelin ısıtılarak kalıptan akıtılması ve oluşan boşluğa bronz dökülmesi esasına dayanır.'),
  ('Toz pigmentlerin çok az miktarda kitre zamkı veya selüloz bağlayıcı ile sıkıştırılmasıyla üretilen, kadifemsi ve mat doku veren boyama çubuğu hangisidir?', 'Kuru pastel', ['Yağlı pastel', 'Akrilik kalem', 'Mum boya'], 'Kuru pastel, düşük bağlayıcı ve yüksek saf pigment oranı sayesinde kağıt üzerinde tebeşirimsi, mat ve kolay dağılan bir etki bırakır.'),
  ('Pigmentlerin kuruyan yağlar yerine balmumu ve kurumayan mineral yağlarla bağlanmasıyla üretilen, fiksatif gerektirmeyen yoğun dokulu çizim çubuğu nedir?', 'Yağlı pastel', ['Kuru pastel', 'Sulu boya kalemi', 'Söğüt füzeni'], 'Yağlı pastel, mum ve yağ bazlı bağlayıcısı sayesinde kağıda güçlü tutunan, toz bırakmayan ve kremsi sürüş sağlayan bir malzemedir.'),
  ('Rönesans döneminde bir sipariş sözleşmesinde altının yanı sıra en pahalı kalem olarak özellikle doğal ultramarin şartı koşulmasının temel nedeni nedir?', 'Hammaddesi olan lapis lazulinin yalnızca uzak coğrafyalardan zorlu süreçlerle getirilip zahmetle saflaştırılması', ['Uygulandığı tuval yüzeyinde birkaç saat içinde çatlamadan kuruyabilen tek mavi boya türü olması', 'Yağlı boya dışında hiçbir bağlayıcı ile karışmadığı için özel simya atölyelerinde üretilmesi', 'İçeriğindeki cıva ve kurşun minerallerinin kraliyet tekelindeki madenlerden çıkarılması'], 'Afganistan\'daki Badahşan madenlerinden getirilen lapis lazuliden saf pigment ayıklamak çok masraflı olduğundan ultramarin statü sembolü sayılmıştır.'),
  ('Mağara duvarlarındaki aşı boyası (okr) resimlerin binlerce yıl boyunca renklerini hiç kaybetmeden günümüze ulaşabilmesini sağlayan temel kimyasal özellik nedir?', 'Demir oksit minerallerinden oluşan inorganik yapısının ışık ve neme karşı son derece kararlı olması', ['Hayvansal yağlarla karıştırıldığında kaya yüzeyiyle birleşerek camlaşmış bir sır tabakası oluşturması', 'Karanlık mağara ortamında bakteriler tarafından sürekli yenilenen organik boyarmaddeler içermesi', 'Kireçtaşı kayalarındaki karbonatla tepkimeye girerek zamanla saf kurşun sülfüre dönüşmesi'], 'Aşı boyaları doğada zaten oksitlenmiş demir mineralleri içerdiğinden ultraviyole ışığa ve atmosferik koşullara karşı kalıcıdır.'),
  ('Akademik desen eğitiminde öğrencilerin çizime kurşun kalem yerine çoğunlukla söğüt füzeni ile başlatılmasının pedagojik ve teknik gerekçesi nedir?', 'Geniş yüzeylerde hızlı tonlama sağlaması ve bezle kolayca silinerek oran-orantı düzeltmelerine izin vermesi', ['Kağıt liflerine anında nüfuz ederek öğrencinin hatalı çizgileri silmesini tamamen engellemesi', 'Bastırma şiddetinden bağımsız olarak her zaman tek tip ince ve keskin kontur çizgileri üretmesi', 'Fiksatif gerektirmeden üst üste yağlı boya katmanları uygulanmasına doğrudan olanak tanıması'], 'Yumuşak füzen, bilek ve kol hareketiyle bütünsel ışık-gölge lekeleri kurmayı kolaylaştırır ve hataların hamur silgiyle hızla düzeltilmesini sağlar.'),
  ('Çini mürekkebiyle yapılmış bir illüstrasyon kuruduktan sonra üzerine sulu boya ile renklendirme yapıldığında siyah çizgilerin dağılmamasının sebebi nedir?', 'Mürekkebin içindeki gomalak reçinesinin kuruduğunda suda çözünmeyen koruyucu bir film oluşturması', ['Karbon siyahı taneciklerinin kağıttaki selüloz lifleriyle asidik bir yanma tepkimesine girmesi', 'Çini mürekkebinin yalnızca keten tohumu yağı ile inceltilebilen yağ bazlı bir boya olması', 'Uygulama öncesinde mürekkebin içine yüksek oranda kurşun beyazı kurutucusu eklenmesi'], 'Geleneksel çini mürekkebinde bulunan şellak (gomalak), kuruma sonrasında suya dirençli bir polimer tabaka yaratarak mürekkebin yayılmasını önler.'),
  ('Kil ile yapılan büyük boyutlu bir modelaj heykelinin iç kısmına "armatür" adı verilen metal veya ahşap iskelet yerleştirilmesinin amacı nedir?', 'Ağır ve yumuşak kil kütlesinin yerçekimi etkisiyle çökmesini ve deforme olmasını engellemek', ['Heykel fırınlanırken ısının merkezden dış yüzeye doğru eşit hızda yayılmasını sağlamak', 'Bronz döküm aşamasında erimiş metalin kalıp içine akacağı kanalları önceden oluşturmak', 'Kil kuruduktan sonra yüzeyde yeşilimsi bir patina tabakasının oluşmasını hızlandırmak'], 'Islak kil kendi ağırlığını taşıyamayacak kadar plastik olduğundan, dikey ve uzantılı formları ayakta tutmak için iç taşıyıcı iskelet (armatür) şarttır.'),
  ('Yontma tekniğiyle mermer çalışan bir heykeltıraşın modelaj çalışan bir sanatçıya kıyasla çok daha temkinli ilerlemek zorunda olmasının nedeni nedir?', 'Eksiltmeye dayalı bir süreç olduğundan bloktan yanlışlıkla koparılan parçanın geri eklenememesi', ['Mermerin hava ile temas ettiğinde sertleşerek keski darbelerine karşı kırılgan hale gelmesi', 'Taş kütlenin içindeki metal armatür noktalarına çarpmamak için sürekli ölçüm yapılması', 'Yontma işleminde fiksatif kullanılmadığı için yüzey dokusunun dokunmayla hemen bozulması'], 'Yontma eksiltici (subtractive) bir tekniktir; taştan veya ahşaptan fazla parça kırıldığında formu eski haline döndürmek mümkün değildir.'),
  ('Açık havada sergilenen bronz bir anıt heykelin yüzeyinde oluşan doğal patinanın koruma uzmanları tarafından kazınmayıp korunmasının temel nedeni nedir?', 'Oluşan ince oksit tabakasının alttaki metali atmosferik korozyona karşı koruyan bir kalkan görevi görmesi', ['Patina kazındığında bronz alaşımındaki kalayın buharlaşarak heykelin hızla erimesine yol açması', 'Yeşil tabakanın heykelin içindeki kil çekirdeğin nem alarak şişmesini tamamen durdurması', 'Patinanın güneş ışığını yansıtarak bronzun yaz aylarında genleşip çatlamasını engellemesi'], 'Kararlı patina (özellikle broşantit yapılı tabaka), metal ile dış ortam arasındaki teması keserek korozyonun derine işlemesini önler.'),
  ('Sangin kaleminin Barok ve Rokoko dönemlerindeki figür eskizlerinde siyah tebeşir ve beyaz tebeşirle birlikte ("trois crayons" tekniği) kullanılmasının sağladığı avantaj nedir?', 'Sıcak kızıl tonuyla insan teninin canlılığını verirken siyah ve beyazla tam bir ışık-gölge hacmi yaratması', ['Kağıt yüzeyini su geçirmez hale getirerek üzerine doğrudan fresk sıvası uygulanmasını sağlaması', 'Üç kalemin kimyasal tepkimesiyle kağıt üzerinde kalıcı Prusya mavisi gölgeler oluşturması', 'Fiksatif kullanılmadan rulo halinde saklandığında çizgilerin birbirine hiç bulaşmamasını garantilemesi'], 'Sıcak sangin orta tonları ve ten sıcaklığını, siyah tebeşir derin gölgeleri, beyaz tebeşir ise ışıkları vererek zengin bir plastik etki doğurur.'),
];
